sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float twist;
uniform float radius;
uniform float falloff;
uniform float zoom;
uniform float spin;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float rr = radius * length(size) * 0.5;
    float t = saturate(1.0 - length(d) / rr);
    t = falloff < 0.5 ? t * t * (3.0 - 2.0 * t) : (falloff < 1.5 ? t : step(0.0001, t));
    float a = (radians(twist) + radians(spin) * time) * t;
    float2 p = rot2(d, a) / mix(1.0, zoom, t);
    return fin(c, tex(ctr + p), opacity);
}
